import{_ as e,o as l,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-11-13:: Ceph DocUBetter Meeting","description":"","frontmatter":{"title":"2019-11-13:: Ceph DocUBetter Meeting","date":"2019-11-13T00:00:00.000Z","updated":"2019-11-18T00:00:00.000Z","tags":["Ceph文档","分布式存储","Sphinx模板","网站更新","社区日历"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-13_-_-_Ceph_DocUBetter_Meeting.md","filePath":"posts/2019/2019-11-13_-_-_Ceph_DocUBetter_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-11-13_-_-_Ceph_DocUBetter_Meeting.md"};function s(n,t,a,p,g,_){return l(),i("div",null,[...t[0]||(t[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Zach Dover（文档编写人员）、Jack、Gary、Sage、Patrick等</p><p><strong>会议主题</strong>： 讨论Ceph文档的更新和改进计划</p><p><strong>关键细节</strong>：</p><ul><li><strong>Zach Dover介绍</strong>： Zach Dover是新加入的文档编写人员，负责Ceph文档的编写工作。他来自美国，在澳大利亚居住了8年，对科幻文学和计算机网络有浓厚的兴趣。</li><li><strong>文档编写计划</strong>： <ul><li>Zach正在编写Ceph的入门指南，目标是使其尽可能用户友好。</li><li>他计划在下周完成指南的编写，并希望得到团队的审核。</li><li>除了入门指南，Zach还将更新硬件和操作系统推荐页面。</li></ul></li><li><strong>RST工具讨论</strong>： <ul><li>团队讨论了是否需要将RST工具替换成其他语言，以简化文档编写流程。</li><li>大部分成员认为目前没有更换工具的必要，但可以列出RST工具的不足之处，以便寻找替代方案。</li></ul></li><li><strong>Sphinx模板更新</strong>： <ul><li>Sage建议更新Sphinx模板，以提高文档的可读性和美观性。</li><li>他将调查现有的Sphinx模板，并选择一个合适的模板进行更新。</li></ul></li><li><strong>网站更新</strong>： <ul><li>会议讨论了网站更新计划，包括添加社区日历和改进着陆页。</li><li>Sage建议将网站从WordPress迁移到静态站点生成器，以便更好地维护。</li></ul></li><li><strong>着陆页改进</strong>： <ul><li>Zach指出当前着陆页存在信息不足、结构混乱等问题。</li><li>他建议添加图片和链接，以改善用户体验。</li></ul></li><li><strong>Ceph安装过程</strong>： <ul><li>会议中讨论了Ceph的安装过程，包括文档F comm、Doc&#39;s master bootstrap等。</li></ul></li></ul><p><strong>决定的事项</strong>：</p><ul><li>Zach将继续编写Ceph的入门指南，并更新硬件和操作系统推荐页面。</li><li>Sage将调查Sphinx模板，并选择一个合适的模板进行更新。</li><li>Sage将领导网站更新项目，包括添加社区日历和改进着陆页。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Zach将在下周完成入门指南的编写，并提交给团队审核。</li><li>Sage将调查Sphinx模板，并选择一个合适的模板进行更新。</li><li>Sage将领导网站更新项目，并与团队沟通具体细节。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了Ceph的硬件和软件推荐页面需要更新。</li><li>讨论了如何标记旧文档并更新导航。</li><li>讨论了在着陆页上添加图片和链接的必要性。</li></ul>',12)])])}const u=e(r,[["render",s]]);export{c as __pageData,u as default};
